INSERT INTO pep_category (country_iso, code, label, kind, risk_class, sort_order, legal_reference)
VALUES ('IE', 'IE-AMLR', 'Conseillers des conseils locaux (couche étendue, règlement (UE) 2024/1624)', 'AMLR', 3, 11,
        'Règlement (UE) 2024/1624 (AMLR) ; hors liste de l''article 37 du Criminal Justice Act 2010');

INSERT INTO pep_function (category_id, label, institution, expected_holders)
SELECT c.id, 'Conseiller d''un conseil local (Dublin City, Dún Laoghaire-Rathdown)', 'Local authorities', 103
FROM pep_category c WHERE c.country_iso = 'IE' AND c.code = 'IE-AMLR';
